from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Callable

from secretscan.config import DEFAULT_SHELL_HISTORY_FILES
from secretscan.model import Finding, Module, ModuleStatus
from secretscan.rules.rule import CompiledRule
from secretscan.scanner.content import scan_lines

_ZSH_EXTENDED_HISTORY = re.compile(r"^: \d+:\d+;")


def _decode_zsh_meta_quoting(s: str) -> str:
    b = s.encode("latin-1", errors="replace")
    if 0x83 not in b:
        return s
    out = bytearray()
    i = 0
    while i < len(b):
        if b[i] == 0x83 and i + 1 < len(b):
            out.append(b[i + 1] ^ 0x20)
            i += 2
        else:
            out.append(b[i])
            i += 1
    return out.decode("utf-8", errors="replace")


def shell_history_scan(
    rules: list[CompiledRule],
    emit: Callable[[Finding], None],
    reveal_length: bool = False,
    allow_matcher: Callable[[str], bool] | None = None,
) -> ModuleStatus:
    status = ModuleStatus(module=Module.SHELL_HISTORY)
    home = str(Path.home())

    for rel in DEFAULT_SHELL_HISTORY_FILES:
        path = os.path.join(home, rel)
        status.attempted += 1

        try:
            with open(path, "r", errors="replace") as f:
                raw_lines = f.readlines()
        except OSError:
            status.skipped += 1
            continue

        commands: list[str] = []
        for raw in raw_lines:
            cmd = _ZSH_EXTENDED_HISTORY.sub("", raw.rstrip("\n\r"))
            cmd = _decode_zsh_meta_quoting(cmd)
            commands.append(cmd)

        scan_lines(
            commands,
            rules,
            path,
            Module.SHELL_HISTORY,
            emit,
            reveal_length=reveal_length,
            allow_matcher=allow_matcher,
        )
        status.accessed += 1

    status.note = "only files that exist and are readable by the current user are scanned"
    return status
